    .{ .name = "SPLIT", .kind = .subroutine, .args = "STRING,SET,POS,BACK=back", .doc = "SPLIT(STRING,SET,POS,BACK=back) finds the next character of STRING that is in SET, after or before position POS." },
    .{ .name = "SPREAD", .kind = .function, .args = "SOURCE,DIM,NCOPIES", .doc = "SPREAD(SOURCE,DIM,NCOPIES) replicates a SOURCE array NCOPIES times along a specified dimension DIM." },
